public final class Solution {
    public static byte[] decodeHex(String text) {
        if (text == null || text.isEmpty()) {
            return new byte[0];
        }

        int len = text.length();
        if (len % 2 != 0) {
            return null;
        }

        byte[] result = new byte[len / 2];
        int i = 0;
        while (i < len - 1) {
            char c1 = text.charAt(i);
            char c2 = text.charAt(i + 1);

            if (!Character.isDigit(c1) || !Character.isDigit(c2)) {
                return null;
            }

            int hexVal = 0;
            if (Character.isLowerCase(c1)) {
                hexVal = Character.getNumericValue(c1) - 0x20;
            } else {
                hexVal = Character.getNumericValue(c1);
            }

            if (Character.isLowerCase(c2)) {
                hexVal = hexVal * 16 + Character.getNumericValue(c2) - 0x20;
            } else {
                hexVal = hexVal * 16 + Character.getNumericValue(c2);
            }

            if (hexVal >= 0 && hexVal < 256) {
                result[i] = (byte) hexVal;
                i += 2;
            } else {
                return null;
            }
        }

        return result;
    }
}

